'use strict';
const assert = require('node:assert/strict');
const { createParser, parse } = require('./src/csv');

const eq = (a, b) => assert.deepEqual(a, b);
eq(parse(''), []);
eq(parse('\uFEFF'), []);
eq(parse('\n'), [['']]);
eq(parse('\n\n'), [[''], ['']]);
eq(parse('a\n'), [['a']]);
eq(parse('a\r\nb\rc\n'), [['a'], ['b'], ['c']]);
eq(parse('a"b,c"'), [['a"b', 'c"']]);
eq(parse('"x\r\ny\rz"'), [['x\r\ny\rz']]);
eq(parse('""'), [['']]);
eq(parse('\uFEFFa,\uFEFF'), [['a', '\uFEFF']]);
eq(parse('a;b,c', { delimiter: ';' }), [['a', 'b,c']]);
eq(parse('a\tb', { delimiter: '\t' }), [['a', 'b']]);
eq(parse('', { header: true }), []);
eq(parse('x,x\n1', { header: true }), [{ x: '1', x_2: '' }]);
for (const d of ['"', '\r', '\n', '', 'ab', 5, null]) assert.throws(() => createParser({ delimiter: d }), RangeError);
assert.throws(() => createParser().push(5), TypeError);
assert.throws(() => parse('"a" ,b'), /line 1/);
assert.throws(() => parse('"a\r\nb\nc\rd" x'), (e) => e instanceof SyntaxError && /line 4/.test(e.message));
assert.throws(() => parse('x\r\n"abc\n'), (e) => e instanceof SyntaxError && /line 3/.test(e.message));

// lifecycle
const p = createParser();
eq(p.push('a\r'), [['a']]);
eq(p.push('\nb'), []);
eq(p.end(), [['b']]);
eq(p.end(), []);
assert.throws(() => p.push(''), Error);

// every 2- and 3-way split of inputs gives same records and line numbers
const inputs = [
  '\uFEFFa,"b""c",d\r\n"e\r\nf",g\rh\n\n"",x"y\r\n',
  'a,"""",\r\r\n\n"q\r\n"\r\nz',
  '"a\r\nb\r\n"x',
  '"a\r\n\r\nb',
  '\uD83D\uDE00,"\uD83D\uDE00"\r\n',
];
const run = (chunks) => {
  const pr = createParser();
  const out = [];
  try {
    for (const c of chunks) out.push(...pr.push(c));
    out.push(...pr.end());
    return out;
  } catch (e) {
    return e.name + ':' + e.message;
  }
};
for (const s of inputs) {
  const whole = run([s]);
  for (let i = 0; i <= s.length; i++) {
    for (let j = i; j <= s.length; j++) {
      eq(run([s.slice(0, i), '', s.slice(i, j), s.slice(j)]), whole);
    }
  }
  console.log(JSON.stringify(whole));
}
// pushes return records immediately
const q = createParser();
eq(q.push('a,b\nc'), [['a', 'b']]);
eq(q.push('\r'), [['c']]);
eq(q.push('\n'), []);
eq(q.end(), []);
console.log('ok');

